package com.xav.friendsglobalchatqol;

import java.awt.Rectangle;

/**
 * A single friend chat message that is pinned to the top of the chatbox
 * until the player clicks the tick button to dismiss it.
 */
class PinnedMessage
{
	private final long id;
	private final String sender;
	private final String text;

	/**
	 * The on-screen bounds of this message's tick button, in canvas
	 * coordinates. Recalculated every time the overlay renders (on the
	 * client thread) and read by {@link FriendPinMouseListener} when a
	 * click comes in (on the input thread) - volatile so a click always
	 * sees the most recently rendered position rather than a stale one.
	 */
	private volatile Rectangle tickBounds;

	PinnedMessage(long id, String sender, String text)
	{
		this.id = id;
		this.sender = sender;
		this.text = text;
	}

	long getId()
	{
		return id;
	}

	String getSender()
	{
		return sender;
	}

	String getText()
	{
		return text;
	}

	Rectangle getTickBounds()
	{
		return tickBounds;
	}

	void setTickBounds(Rectangle tickBounds)
	{
		this.tickBounds = tickBounds;
	}
}
